try {
    $p=$id?produtores_query('SELECT p.*,f.arquivo,f.aba,f.referencia FROM produtores p JOIN peaf_fontes f ON f.id=p.fonte_id WHERE p.id=?',[$id])->fetch():false;
} catch (Throwable $err) { produtores_unavailable($err); }
